# =============================================================================
# menus.py - 메뉴 데이터베이스 (메뉴 목록 + 각 메뉴의 "특징표")
#
# 추천의 재료가 되는 데이터입니다. 로직(계산)은 recommender.py 에 있고,
# 이 파일에는 "어떤 메뉴가 어떤 특징을 가졌는지" 데이터만 둡니다.
# → 데이터와 로직을 나누면, 메뉴를 추가할 때 로직을 건드리지 않아도 됩니다.
#
# 메뉴 1개의 모양:
#   {
#     "id": 1,                      # 고유 번호 (브라우저와 서버가 메뉴를 주고받을 때 이 번호로 구분)
#     "name": "김치찌개",            # 화면에 보일 이름
#     "emoji": "🍲",                # 화면에 보일 그림
#     "tags": [...],                # 특징표(태그). 클릭 반응에 따라 이 태그들의 점수가 오르내립니다.
#     "meals": [...],               # 어울리는 식사 시간 (아침/점심/저녁/야식)
#     "ingredients": [...],         # 주요 재료. 사용자가 입력한 재료와 비교할 때 사용
#   }
#
# 태그 종류 (같은 태그 이름을 정확히 써야 점수 계산이 맞게 됩니다):
#   종류   : 한식, 중식, 일식, 양식, 분식, 아시안, 패스트푸드   ← 메뉴마다 딱 1개
#   형태   : 밥, 면, 빵, 고기, 국물
#   맛     : 매움, 담백, 달달, 기름짐
#   온도   : 따뜻함, 차가움
#   양     : 든든, 가벼움
#   상황   : 혼밥(혼자 먹기 좋음), 나눠먹기(여럿이 좋음), 특별함(기분 내기 좋음)
#
# 메뉴를 추가하고 싶으면? 아래 리스트에 같은 모양으로 한 줄 추가하고 id 만 겹치지 않게 하면 됩니다.
# =============================================================================

